-- 07 - server-side moderation (F11), safe orphan cleanup (F08), email cap (Resend) - migrations 0138-0140
-- Always ends in RAISE EXCEPTION so the whole transaction rolls back (nothing persists; pg_net requests queued
-- by the triggers are rolled back with it, so no function is called and nothing reaches Gemini).
-- Run from the repo root:  npx supabase db query --linked -f supabase/tests/07_server_moderation.sql
-- Result is in the error message ("RESULTS: [...]").
do $tt$
declare
  res jsonb := '[]'::jsonb;
  sfx text := substr(md5(random()::text), 1, 6);
  j jsonb; n bigint; n2 bigint; b boolean; t text; r record; sid uuid; sid2 uuid; ev uuid;
  u_a uuid := gen_random_uuid(); u_b uuid := gen_random_uuid(); u_adm uuid := gen_random_uuid();
  v1 uuid; v2 uuid; v3 uuid; v4 uuid; v5 uuid; v6 uuid; c1 uuid; c2 uuid; s1 uuid; base_sum integer;
  m1 uuid; m2 uuid; m3 uuid; m4 uuid; m5 uuid; k1 text := 'videos/aa/' || repeat('1', 32) || '.jpg'; k2 text := 'videos/bb/' || repeat('2', 32) || '.jpg';
  k3 text := 'videos/cc/' || repeat('3', 32) || '.jpg'; k4 text := 'videos/other-project/legacy.mp4'; k5 text := 'videos/dd/' || repeat('5', 32) || '.jpg';
begin
 begin
  insert into auth.users (id, aud, role, email, raw_user_meta_data, created_at, updated_at)
  select x.id, 'authenticated', 'authenticated', 'tt-' || x.h || '@example.invalid',
         jsonb_build_object('handle', 'tt_' || x.h || '_' || sfx), now(), now()
    from (values (u_a, 'a'),(u_b, 'b'),(u_adm, 'adm')) x(id, h);
  update public.profiles set is_admin = true where id = u_adm;
  select count(*) into n from public.videos where hidden_reason = 'pending_review';
  res := res || jsonb_build_object('t', '7. baseline: no existing video is pending_review', 'pass', n = 0, 'ev', n::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
insert into public.videos (user_id, description, video_url, thumbnail, privacy, is_draft) values (u_a, 'tt v1', 'https://example.invalid/v.mp4', 'https://example.invalid/t.jpg', 'public', false) returning id into v1;
insert into public.videos (user_id, description, video_url, thumbnail, privacy, is_draft) values (u_a, 'tt draft', 'https://example.invalid/v.mp4', 'https://example.invalid/t.jpg', 'public', true) returning id into v2;
select count(*) into n from public.videos where id = v1;
res := res || jsonb_build_object('t', '7a. owner can still see own pending video', 'pass', coalesce((n = 1)::boolean,false), 'ev', ('')::text);
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7a. new video by a normal user is stored hidden as pending_review', 'pass', coalesce(((select is_hidden and hidden_reason = 'pending_review' from public.videos where id = v1))::boolean,false), 'ev', ('')::text);
res := res || jsonb_build_object('t', '7a. a screening row was opened for it', 'pass', coalesce((exists (select 1 from public.content_screening where kind='video' and target_id = v1 and status='pending' and not rescreen))::boolean,false), 'ev', ('')::text);
res := res || jsonb_build_object('t', '7a. a pg_net dispatch was queued (attempts = 1)', 'pass', coalesce(((select attempts from public.content_screening where kind='video' and target_id = v1) = 1)::boolean,false), 'ev', ((select attempts from public.content_screening where kind='video' and target_id = v1))::text);
res := res || jsonb_build_object('t', '7a. a draft is not hidden and not screened yet', 'pass', coalesce(((select not is_hidden from public.videos where id = v2) and not exists (select 1 from public.content_screening where target_id = v2))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_b, 'role','authenticated')::text, true); set local role authenticated;
select count(*) into n from public.videos where id = v1;
res := res || jsonb_build_object('t', '7b. another user cannot see the pending video', 'pass', coalesce((n = 0)::boolean,false), 'ev', (n)::text);
reset role; perform set_config('request.jwt.claims','',true);
perform set_config('request.jwt.claims', json_build_object('role','anon')::text, true); set local role anon;
select count(*) into n from public.videos where id = v1;
res := res || jsonb_build_object('t', '7b. anon cannot see the pending video', 'pass', coalesce((n = 0)::boolean,false), 'ev', (n)::text);
reset role; perform set_config('request.jwt.claims','',true);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
update public.videos set is_hidden = false, hidden_reason = null where id = v1;
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7c. the owner cannot un-hide a pending video', 'pass', coalesce(((select is_hidden from public.videos where id = v1))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
update public.videos set is_draft = false where id = v2;
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7d. publishing a draft hides it as pending and opens a screening', 'pass', coalesce(((select is_hidden and hidden_reason='pending_review' from public.videos where id = v2) and exists (select 1 from public.content_screening where target_id = v2 and status='pending'))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_adm, 'role','authenticated')::text, true); set local role authenticated;
insert into public.videos (user_id, description, video_url, thumbnail, privacy, is_draft) values (u_adm, 'tt admin', 'https://example.invalid/v.mp4', 'https://example.invalid/t.jpg', 'public', false) returning id into v3;
reset role; perform set_config('request.jwt.claims','',true);
insert into public.videos (user_id, description, video_url, thumbnail, privacy, is_draft) values (u_a, 'tt service', 'https://example.invalid/v.mp4', 'https://example.invalid/t.jpg', 'public', false) returning id into v4;
res := res || jsonb_build_object('t', '7e. admin and service-role inserts are not hidden', 'pass', coalesce(((select not is_hidden from public.videos where id = v3) and (select not is_hidden from public.videos where id = v4))::boolean,false), 'ev', ('')::text);
select id into sid from public.content_screening where target_id = v1;
t := public.screening_finish(sid, 'allow');
perform set_config('request.jwt.claims', json_build_object('sub', u_b, 'role','authenticated')::text, true); set local role authenticated;
select count(*) into n from public.videos where id = v1;
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7f. allow releases the video (visible to others)', 'pass', coalesce((n = 1 and t = 'ok' and (select hidden_reason is null from public.videos where id = v1))::boolean,false), 'ev', (t)::text);
res := res || jsonb_build_object('t', '7f. a second finish is a no-op', 'pass', coalesce((public.screening_finish(sid, 'block') = 'already_ok' and (select not is_hidden from public.videos where id = v1))::boolean,false), 'ev', ('')::text);
select id into sid from public.content_screening where target_id = v2;
t := public.screening_finish(sid, 'review', null, null, 'harassment', 0.5);
res := res || jsonb_build_object('t', '7g. review releases the video AND queues it for admins', 'pass', coalesce((t = 'review' and (select not is_hidden from public.videos where id = v2) and exists (select 1 from public.reports where target_type='video' and target_id = v2 and reporter_id is null and status='pending'))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
insert into public.videos (user_id, description, video_url, thumbnail, privacy, is_draft) values (u_a, 'tt v5', 'https://example.invalid/v.mp4', 'https://example.invalid/t.jpg', 'public', false) returning id into v5;
reset role; perform set_config('request.jwt.claims','',true);
select id into sid from public.content_screening where target_id = v5;
t := public.screening_finish(sid, 'block', null, null, 'hate', 0.95);
perform set_config('request.jwt.claims', json_build_object('sub', u_b, 'role','authenticated')::text, true); set local role authenticated;
select count(*) into n from public.videos where id = v5;
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7h. block keeps the video hidden (moderation_block) and queues it', 'pass', coalesce((t = 'blocked' and n = 0 and (select hidden_reason from public.videos where id = v5) = 'moderation_block' and exists (select 1 from public.reports where target_id = v5 and status='pending'))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
insert into public.videos (user_id, description, video_url, thumbnail, privacy, is_draft) values (u_a, 'tt v6', 'https://example.invalid/v.mp4', 'https://example.invalid/t.jpg', 'public', false) returning id into v6;
reset role; perform set_config('request.jwt.claims','',true);
select id into sid from public.content_screening where target_id = v6;
t := public.screening_finish(sid, 'unavailable', null, 'timeout');
res := res || jsonb_build_object('t', '7i. Gemini unavailable: the video stays hidden for now', 'pass', coalesce((t = 'unavailable' and (select is_hidden from public.videos where id = v6))::boolean,false), 'ev', ('')::text);
j := public.screening_sweep();
res := res || jsonb_build_object('t', '7i. a young unscreened row is not released early', 'pass', coalesce(((select is_hidden from public.videos where id = v6))::boolean,false), 'ev', (j::text)::text);
update public.content_screening set created_at = now() - interval '10 minutes', last_attempt_at = now() where id = sid;
j := public.screening_sweep();
res := res || jsonb_build_object('t', '7i. after the timeout the sweeper releases it (ok-by-timeout)', 'pass', coalesce(((select not is_hidden from public.videos where id = v6) and (select status from public.content_screening where id = sid) = 'released_timeout')::boolean,false), 'ev', (j::text)::text);
res := res || jsonb_build_object('t', '7i. ...and files an admin queue entry + an unavailable event', 'pass', coalesce((exists (select 1 from public.reports where target_id = v6 and reporter_id is null and status='pending') and exists (select 1 from public.moderation_events where target_id = v6 and outcome = 'unavailable'))::boolean,false), 'ev', ('')::text);
res := res || jsonb_build_object('t', '7i. ...and an admin_logs line', 'pass', coalesce((exists (select 1 from public.admin_logs where action = 'screening_released_unscreened' and created_at > now() - interval '1 minute'))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
update public.videos set description = 'tt edited caption' where id = v1;
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7j. editing a visible video re-screens it without hiding it first', 'pass', coalesce(((select not is_hidden from public.videos where id = v1) and exists (select 1 from public.content_screening where target_id = v1 and rescreen and status='pending'))::boolean,false), 'ev', ('')::text);
select id into sid from public.content_screening where target_id = v1 and rescreen;
t := public.screening_finish(sid, 'block', null, null, 'hate', 0.9);
res := res || jsonb_build_object('t', '7j. a blocked edit hides the video', 'pass', coalesce(((select is_hidden and hidden_reason='moderation_block' from public.videos where id = v1))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_b, 'role','authenticated')::text, true); set local role authenticated;
insert into public.comments (video_id, user_id, text) values (v2, u_b, 'tt hello comment') returning id into c1;
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7k. new comment is stored hidden as pending_review', 'pass', coalesce(((select is_hidden and hidden_reason='pending_review' from public.comments where id = c1))::boolean,false), 'ev', ('')::text);
res := res || jsonb_build_object('t', '7k. its notification is held back while pending', 'pass', coalesce((not exists (select 1 from public.notifications where payload->>'comment_id' = c1::text))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
select count(*) into n from public.comments where id = c1;
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7k. other users cannot read the pending comment', 'pass', coalesce((n = 0)::boolean,false), 'ev', (n)::text);
select id into sid from public.content_screening where kind='comment' and target_id = c1;
t := public.screening_finish(sid, 'allow');
res := res || jsonb_build_object('t', '7k. allow releases the comment and sends the held notification', 'pass', coalesce(((select not is_hidden from public.comments where id = c1) and exists (select 1 from public.notifications where payload->>'comment_id' = c1::text))::boolean,false), 'ev', (t)::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_b, 'role','authenticated')::text, true); set local role authenticated;
insert into public.comments (video_id, user_id, text) values (v2, u_b, 'tt second comment') returning id into c2;
reset role; perform set_config('request.jwt.claims','',true);
select id into sid from public.content_screening where kind='comment' and target_id = c2;
t := public.screening_finish(sid, 'block', null, null, 'harassment', 0.95);
res := res || jsonb_build_object('t', '7l. a blocked comment stays hidden and never notifies', 'pass', coalesce(((select is_hidden from public.comments where id = c2) and not exists (select 1 from public.notifications where payload->>'comment_id' = c2::text))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
insert into public.stories (user_id, media_url, media_kind) values (u_a, 'https://example.invalid/s.jpg', 'image') returning id into s1;
update public.stories set is_hidden = false, hidden_reason = null where id = s1;
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7m. new story is hidden pending review; owner cannot un-hide it', 'pass', coalesce(((select is_hidden and hidden_reason='pending_review' from public.stories where id = s1) and exists (select 1 from public.content_screening where kind='story' and target_id = s1))::boolean,false), 'ev', ('')::text);
select id into sid from public.content_screening where kind='story' and target_id = s1;
t := public.screening_finish(sid, 'allow');
res := res || jsonb_build_object('t', '7m. allow releases the story', 'pass', coalesce(((select not is_hidden from public.stories where id = s1))::boolean,false), 'ev', (t)::text);
update public.screening_config set enabled = false;
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
insert into public.videos (user_id, description, video_url, thumbnail, privacy, is_draft) values (u_a, 'tt kill', 'https://example.invalid/v.mp4', 'https://example.invalid/t.jpg', 'public', false) returning id into v3;
reset role; perform set_config('request.jwt.claims','',true);
res := res || jsonb_build_object('t', '7n. kill switch: new content is not hidden', 'pass', coalesce(((select not is_hidden from public.videos where id = v3))::boolean,false), 'ev', ('')::text);
update public.screening_config set enabled = true;
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
insert into public.videos (user_id, description, video_url, thumbnail, privacy, is_draft) values (u_a, 'tt back on', 'https://example.invalid/v.mp4', 'https://example.invalid/t.jpg', 'public', false) returning id into v3;
reset role; perform set_config('request.jwt.claims','',true);
update public.screening_config set enabled = false;
j := public.screening_sweep();
update public.screening_config set enabled = true;
res := res || jsonb_build_object('t', '7n. kill switch: sweeper releases everything pending at once', 'pass', coalesce(((select not is_hidden from public.videos where id = v3) and not exists (select 1 from public.content_screening where status in ('pending','unavailable') and kind='video' and target_id = v3))::boolean,false), 'ev', (j::text)::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
begin perform public.screening_finish(gen_random_uuid(), 'allow'); res := res || jsonb_build_object('t','7o. users cannot call screening_finish','pass',false,'ev','NO ERROR'); exception when others then res := res || jsonb_build_object('t','7o. users cannot call screening_finish','pass',sqlstate='42501','ev',sqlstate); end;
begin perform count(*) from public.content_screening; res := res || jsonb_build_object('t','7o. users cannot read content_screening','pass',false,'ev','NO ERROR'); exception when others then res := res || jsonb_build_object('t','7o. users cannot read content_screening','pass',sqlstate='42501','ev',sqlstate); end;
reset role; perform set_config('request.jwt.claims','',true);
insert into public.media_objects (id, bucket, key, user_id, size_bytes, content_type, status, created_at) values (gen_random_uuid(), 'videos', k1, u_a, 1000, 'image/jpeg', 'pending', now() - interval '30 hours') returning id into m1;
insert into public.media_objects (id, bucket, key, user_id, size_bytes, content_type, status, created_at) values (gen_random_uuid(), 'videos', k2, u_a, 2000, 'image/jpeg', 'pending', now() - interval '30 hours') returning id into m2;
insert into public.media_objects (id, bucket, key, user_id, size_bytes, content_type, status, created_at) values (gen_random_uuid(), 'videos', k3, u_a, 3000, 'image/jpeg', 'pending', now() - interval '2 hours') returning id into m3;
insert into public.media_objects (id, bucket, key, user_id, size_bytes, content_type, status, created_at) values (gen_random_uuid(), 'videos', k4, u_a, 4000, 'video/mp4', 'pending', now() - interval '30 hours') returning id into m4;
insert into public.media_objects (id, bucket, key, user_id, size_bytes, content_type, status, created_at) values (gen_random_uuid(), 'videos', k5, u_a, 5000, 'image/jpeg', 'stored', now() - interval '30 hours') returning id into m5;
update public.videos set thumbnail = 'https://media.example.invalid/' || k2 where id = v4;
j := public.media_orphan_scan(100, 1);
res := res || jsonb_build_object('t', '8a. scan: only the old, unreferenced, well-formed pending key is a candidate', 'pass', coalesce(((j->>'eligible')::int = 1 and j->'candidates'->0->>'key' = k1 and (j->>'skipped_referenced')::int >= 1 and (j->>'skipped_unrecognised_key')::int >= 1)::boolean,false), 'ev', (j::text)::text);
res := res || jsonb_build_object('t', '8a. a 1 hour min age is coerced to 24 h (the 2 h old row is never a candidate)', 'pass', coalesce((j::text not like '%' || k3 || '%')::boolean,false), 'ev', ('')::text);
res := res || jsonb_build_object('t', '8b. the referenced key is not a candidate; neither is the foreign-shaped key', 'pass', coalesce((j::text not like '%' || k2 || '%' and j::text not like '%other-project%')::boolean,false), 'ev', ('')::text);
select count(*) into n from public.media_objects where id in (select (x->>'id')::uuid from jsonb_array_elements(j->'candidates') x) and key = k1;
select count(*) into n2 from public.media_orphan_claim(array[m1, m2, m3, m4, m5], 1);
res := res || jsonb_build_object('t', '8c. claim takes ONLY the safe row out of five', 'pass', coalesce((n2 = 1 and (select status from public.media_objects where id = m1) = 'deleted' and (select status from public.media_objects where id = m2) = 'pending' and (select status from public.media_objects where id = m3) = 'pending' and (select status from public.media_objects where id = m4) = 'pending' and (select status from public.media_objects where id = m5) = 'stored')::boolean,false), 'ev', (n2)::text);
n := public.media_orphan_release(array[m1]);
res := res || jsonb_build_object('t', '8c. release hands the claim back', 'pass', coalesce((n = 1 and (select status from public.media_objects where id = m1) = 'pending')::boolean,false), 'ev', ('')::text);
res := res || jsonb_build_object('t', '8d. dry-run reconcile_config defaults: live = false, enabled = true, min age >= 24', 'pass', coalesce(((select not live and enabled and min_age_hours >= 24 from public.reconcile_config))::boolean,false), 'ev', ('')::text);
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
begin perform public.media_orphan_scan(10, 24); res := res || jsonb_build_object('t','8e. users cannot call media_orphan_scan','pass',false,'ev','NO ERROR'); exception when others then res := res || jsonb_build_object('t','8e. users cannot call media_orphan_scan','pass',sqlstate='42501','ev',sqlstate); end;
reset role; perform set_config('request.jwt.claims','',true);
select coalesce(sum(sent),0) into base_sum from public.email_send_log where day = (now() at time zone 'utc')::date;
update public.email_config set daily_cap = base_sum + 3;
res := res || jsonb_build_object('t', '9a. email cap: 2 + 1 sends are allowed, the 4th is refused', 'pass', coalesce((public.email_send_take('tt', 2) and public.email_send_take('tt', 1) and not public.email_send_take('tt', 1))::boolean,false), 'ev', ('')::text);
res := res || jsonb_build_object('t', '9a. refusal is logged once to admin_logs (email_cap_hit)', 'pass', coalesce(((select count(*) from public.admin_logs where action = 'email_cap_hit' and created_at > now() - interval '1 minute') = 1)::boolean,false), 'ev', ('')::text);
n := (select count(*) from public.admin_logs where action = 'email_cap_hit');
b := public.email_send_take('tt', 1);
res := res || jsonb_build_object('t', '9a. a second refusal the same day does not log again', 'pass', coalesce(((select count(*) from public.admin_logs where action = 'email_cap_hit') = n)::boolean,false), 'ev', ('')::text);
update public.email_config set daily_cap = base_sum + 100, enabled = false;
res := res || jsonb_build_object('t', '9b. email kill switch (enabled=false) refuses sends', 'pass', coalesce((not public.email_send_take('tt', 1))::boolean,false), 'ev', ('')::text);
update public.email_config set enabled = true;
perform set_config('request.jwt.claims', json_build_object('sub', u_a, 'role','authenticated')::text, true); set local role authenticated;
begin perform public.email_send_take('x', 1); res := res || jsonb_build_object('t','9c. users cannot call email_send_take','pass',false,'ev','NO ERROR'); exception when others then res := res || jsonb_build_object('t','9c. users cannot call email_send_take','pass',sqlstate='42501','ev',sqlstate); end;
reset role; perform set_config('request.jwt.claims','',true);

 exception when others then
  reset role;
  res := res || jsonb_build_object('t', 'HARNESS ABORTED (unhandled error)', 'pass', false, 'ev', sqlstate || ' ' || left(sqlerrm, 300));
 end;
  reset role;
  perform set_config('request.jwt.claims', '', true);
  raise exception 'RESULTS: %', res::text;
end
$tt$;
